syntax:
return_type (*function_pointer_name)(parameter_types); // Declaring a function pointer

// Assigning a function to the pointer
function_pointer_name = function_name;

// Calling the function via pointer
result = (*function_pointer_name)(arguments);

code_example:
typedef int (*Operation)(int, int); // Define a function pointer type for functions taking two ints and returning int
int add(int a, int b) { return a + b; }
int multiply(int a, int b) { return a * b; }
void execute_operation(Operation op, int x, int y) {
    printf("Result: %d\n", op(x, y));
}
int main() {
    Operation op = add; // Assign 'add' function to the callback
    execute_operation(op, 5, 3); // Calls add(5, 3)
    op = multiply; // Change callback to 'multiply'
    execute_operation(op, 5, 3); // Calls multiply(5, 3)
    return 0;
}
